import { promises as fs } from 'node:fs';
import * as path from 'node:path';
import * as os from 'node:os';
import * as crypto from 'node:crypto';
import { GEMINI_DIR, homedir } from '../utils/paths.js';
import type { Keychain } from './keychainTypes.js';

/**
 * A record of stored secrets, keyed by service name and then by account.
 */
type KeychainStore = Record<string, Record<string, string>>;

/**
 * A file-based fallback implementation of the {@link Keychain} interface used
 * when the native OS keychain is unavailable. Secrets are persisted to an
 * encrypted file in the user's config directory.
 */
export class FileKeychain implements Keychain {
  private readonly filePath: string;
  private readonly encryptionKey: Buffer;

  constructor() {
    const configDir = path.join(homedir(), GEMINI_DIR);
    this.filePath = path.join(configDir, 'keychain.json');
    this.encryptionKey = this.deriveEncryptionKey();
  }

  private deriveEncryptionKey(): Buffer {
    const salt = `${os.hostname()}-${os.userInfo().username}-gemini-cli`;
    return crypto.scryptSync('gemini-cli-keychain', salt, 32);
  }

  private encrypt(text: string): string {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', this.encryptionKey, iv);

    let encrypted = cipher.update(text, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const authTag = cipher.getAuthTag();

    return iv.toString('hex') + ':' + authTag.toString('hex') + ':' + encrypted;
  }

  private decrypt(encryptedData: string): string {
    const parts = encryptedData.split(':');
    if (parts.length !== 3) {
      throw new Error('Invalid encrypted data format');
    }

    const iv = Buffer.from(parts[0], 'hex');
    const authTag = Buffer.from(parts[1], 'hex');
    const encrypted = parts[2];

    const decipher = crypto.createDecipheriv(
      'aes-256-gcm',
      this.encryptionKey,
      iv,
    );
    decipher.setAuthTag(authTag);

    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  }

  private async ensureDirectoryExists(): Promise<void> {
    const dir = path.dirname(this.filePath);
    await fs.mkdir(dir, { recursive: true, mode: 0o700 });
  }

  private async load(): Promise<KeychainStore> {
    try {
      const data = await fs.readFile(this.filePath, 'utf-8');
      const decrypted = this.decrypt(data);
      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
      return JSON.parse(decrypted) as KeychainStore;
    } catch (error: unknown) {
      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
      const err = error as NodeJS.ErrnoException;
      if (err.code === 'ENOENT') {
        return {};
      }
      throw error;
    }
  }

  private async save(store: KeychainStore): Promise<void> {
    await this.ensureDirectoryExists();
    const encrypted = this.encrypt(JSON.stringify(store));
    await fs.writeFile(this.filePath, encrypted, { mode: 0o600 });
  }

  async getPassword(service: string, account: string): Promise<string | null> {
    const store = await this.load();
    return store[service]?.[account] ?? null;
  }

  async setPassword(
    service: string,
    account: string,
    password: string,
  ): Promise<void> {
    const store = await this.load();
    if (!store[service]) {
      store[service] = {};
    }
    store[service][account] = password;
    await this.save(store);
  }

  async deletePassword(service: string, account: string): Promise<boolean> {
    const store = await this.load();
    const accounts = store[service];
    if (!accounts || !(account in accounts)) {
      return false;
    }

    delete accounts[account];
    if (Object.keys(accounts).length === 0) {
      delete store[service];
    }
    await this.save(store);
    return true;
  }

  async findCredentials(
    service: string,
  ): Promise<Array<{ account: string; password: string }>> {
    const store = await this.load();
    const accounts = store[service] ?? {};
    return Object.entries(accounts).map(([account, password]) => ({
      account,
      password,
    }));
  }
}
